SELECT tblCase.CaseID, tblTimeTableDetail.Bill_ID, tblTimeTableDetail.Tdate, tblTimeTableDetail.Description, tblTimeTableDetail.Tatty, tblTimeTableDetail.Rate, tblTimeTableDetail.Time_, [Last_name] & IIf(IsNull([first_name]),Null," " & [first_name]) AS FullName, Nz([time_],0)*Nz([rate],0) AS Amount, [case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty] AS CaseNo, tblCase.Last_Name, tblCase.First_Name, tblCase.Case_Letter, tblCase.yr, tblCase.Number_, tblCase.Orig_Atty, tblCase.Address, tblCase.State, tblCase.City, tblCase.Zip, tblCase.Matter_type, tblCase.Executor
FROM tblCase INNER JOIN ([TB Time Keeping] INNER JOIN tblTimeTableDetail ON [TB Time Keeping].Bill_ID = tblTimeTableDetail.Bill_ID) ON tblCase.CaseID = [TB Time Keeping].CaseID;